import re

def parse(lines):
    blocks = []
    skip = []
    summary = {'name': 'summary', 'kind': 'kv', 'lines': [], 'records': [{}]}
    legends = {}
    section = None
    cur = None
    spans = None
    hdr_re = re.compile(r'^\s*(\[\d+\]\s+){2,}')
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            cur = None
            continue
        if hdr_re.match(l):
            toks = [(m.start(), m.group(0)) for m in re.finditer(r'\[\d+\]|Instructions:', l)]
            if section and 'Resource pressure' in section:
                lg = legends.get('Resources')
            else:
                lg = legends.get(section)
            names = lg['records'][0] if lg else {}
            spans = []
            for k, (p, t) in enumerate(toks):
                a = 0 if k == 0 else max(p - 1, 0)
                b = toks[k + 1][0] - 1 if k + 1 < len(toks) else None
                n = t.rstrip(':') if t == 'Instructions:' else names.get(t, t)
                spans.append((n, a, b))
            cur = {'name': (section or 'table').lower(), 'kind': 'table', 'lines': [i], 'records': []}
            blocks.append(cur)
            continue
        m = re.match(r'^\[(\d+)\]:\s+(\S.*)$', s) or re.match(r'^\[(\d+)\]\s+-\s+(\S.*)$', s)
        if m:
            lb = legends.get(section)
            if lb is None:
                lb = {'name': ((section or '') + ' legend').strip().lower(), 'kind': 'kv', 'lines': [], 'records': [{}]}
                legends[section] = lb
                blocks.append(lb)
            lb['lines'].append(i)
            lb['records'][0]['[' + m.group(1) + ']'] = m.group(2).strip()
            continue
        if cur is not None and spans:
            rec = {}
            for n, a, b in spans:
                rec[n] = (l[a:b] if b is not None else l[a:]).strip()
            cur['records'].append(rec)
            cur['lines'].append(i)
            continue
        m = re.match(r'^([A-Za-z][^:\[]*):\s*(\S.*)?$', l)
        if m:
            if m.group(2) is None:
                section = m.group(1).strip()
                skip.append(i)
            else:
                summary['records'][0][m.group(1).strip()] = m.group(2).strip()
                summary['lines'].append(i)
            continue
    if summary['lines']:
        blocks.insert(0, summary)
    return {'blocks': blocks, 'skip': skip}
